SELECT CASE WHEN customers.age >= 68 THEN 'high' WHEN customers.age >= 27 THEN 'mid' ELSE 'low' END AS age_bucket, QUARTER(customers.signup_date) AS signup_quarter, COUNT(CASE WHEN accounts.status = 'OPEN' THEN 1 END) AS open_count FROM accounts FULL OUTER JOIN customers ON accounts.customer_id = customers.id GROUP BY CASE WHEN customers.age >= 68 THEN 'high' WHEN customers.age >= 27 THEN 'mid' ELSE 'low' END, QUARTER(customers.signup_date)
